examples.template:
MonarchMessageRow(
    author = MonarchMessageRowAuthor({{author}}),
    time = {{time|millis}},
    now = {{now|millis}},
    reactions = reactions,
    replyCount = {{replyCount}},
    actions = listOf(
        MonarchMessageRowAction({{actions.0}}, onClick = { /* Edit the message. */ }),
        MonarchMessageRowAction({{actions.1}}, onClick = { /* Open the message menu. */ }),
    ),
    onReactionToggle = { emoji, reacted ->
        reactions = reactions.map { item ->
            if (item.emoji == emoji) {
                MonarchReactionBarItem(emoji, count = item.count + if (reacted) 1 else -1, reacted = reacted, label = item.label)
            } else {
                item
            }
        }
    },
    onOpenThread = { /* Open the thread. */ },
) {
    MonarchText({{body}})
}

examples.setupTemplate:
var reactions by remember {
    mutableStateOf(
        listOf(
            MonarchReactionBarItem({{reactions.0.emoji}}, count = {{reactions.0.count}}, reacted = {{reactions.0.reacted}}, label = {{reactions.0.label}}),
            MonarchReactionBarItem({{reactions.1.emoji}}, count = {{reactions.1.count}}, label = {{reactions.1.label}}),
        ),
    )
}

